mapper.select:
SELECT n.internal_notice_id, n.target_scope_code, n.team_id, t.name AS team_name, n.title, n.status_code, n.is_important, n.publish_start_dttm, n.publish_end_dttm, updater.name AS updated_by_name, n.updated_dttm FROM internal_notice n LEFT JOIN team t ON t.team_id = n.team_id JOIN member updater ON updater.member_id = n.updated_by_member_id WHERE n.deleted_dttm IS NULL
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.body LIKE CONCAT('%', #{keyword}, '%'))
AND n.status_code = #{status}
AND n.target_scope_code = #{targetScope}
AND n.team_id = #{teamId}
ORDER BY n.updated_dttm DESC, n.internal_notice_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT n.internal_notice_id, n.target_scope_code, n.team_id, t.name AS team_name, n.title, n.is_important, n.publish_start_dttm, n.publish_end_dttm, (r.internal_notice_read_id IS NOT NULL) AS is_read FROM internal_notice n LEFT JOIN team t ON t.team_id = n.team_id LEFT JOIN internal_notice_read r ON r.internal_notice_id = n.internal_notice_id AND r.member_id = #{memberId} WHERE
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.body LIKE CONCAT('%', #{keyword}, '%'))
AND r.internal_notice_read_id IS NULL
AND n.target_scope_code = #{targetScope}
ORDER BY n.is_important DESC, n.publish_start_dttm DESC, n.internal_notice_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS (
    SELECT 1
    FROM internal_notice n
