)

mapper.insert:
INSERT INTO internal_notice (
    target_scope_code, team_id, title, body, status_code, is_important,
    publish_start_dttm, publish_end_dttm, created_by_member_id,
    updated_by_member_id, published_by_member_id
) VALUES (
    #{targetScope}, #{teamId}, #{title}, #{body}, #{status}, #{important},
    #{publishStartDttm}, #{publishEndDttm}, #{createdByMemberId},
    #{updatedByMemberId}, #{publishedByMemberId}
)

INSERT INTO internal_notice_read (
    internal_notice_id, member_id, first_read_dttm, last_read_dttm
) VALUES (
    #{internalNoticeId}, #{memberId}, #{readDttm}, #{readDttm}
)
ON DUPLICATE KEY UPDATE
    last_read_dttm = VALUES(last_read_dttm)

INSERT INTO internal_notice_attachment (
    internal_notice_id, stored_file_id, display_order
) VALUES (
    #{internalNoticeId}, #{storedFileId}, #{displayOrder}
)

